pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. Initialize the contract (sets _owner to msg.sender)
        c.initialize();

        // 2. Register this test contract as a program operator
        c.updateRoundImplementation(payable(address(0xdeadbeef))); // set roundImplementation to non-zero
        c.updateAlloSettings(address(0xdeadcafe));               // set alloSettings to non-zero

        // 3. In the reference, owner() returns address(this). In the bug, it returns address(0).
        address ownerObserved = c.owner();

        // 4. The bug always returns address(0), so in the reference ownerObserved == address(this) != 0.
        assertTrue(ownerObserved != address(0), "Owner should be non-zero after initialization");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a non-owner account
        address nonOwner = address(0xBEEF);
        vm.prank(nonOwner);
        // Trying to transfer ownership to address(0) should revert in reference
        // but succeed in the buggy version.
        try c.transferOwnership(address(0)) {
            // If it succeeded, reference would fail, buggy passes
            assertTrue(false, "Bug: transferOwnership to zero address succeeded when it should revert");
        } catch {
            // Expected revert in reference: test passes
            assertTrue(true);
        }
    }
}

