pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initial setup: initialize the contract
        c.initialize();

        // Set program operator
        address operator = address(0x123);
        c.programOperators(operator);
        // Since there's no setter for programOperators, we need to directly set it via vm.store or similar
        // But vm.store is not allowed. Alternative: we need to use the existing interface.
        // Actually the contract doesn't have a function to add program operators, so we'll use the owner
        // The owner is the deployer (address(this) in test)
        // Set round implementation to a valid contract
        address roundImpl = address(new DummyRound());
        c.updateRoundImplementation(payable(roundImpl));

        // Set alloSettings
        address allo = address(new DummyAlloSettings());
        c.updateAlloSettings(allo);

        // Now call create with specific parameters
        bytes memory encodedParams = abi.encode(2, "test");
        address ownedBy = address(0x456);

        // Before the bug: transferOwnership(address(0)) would revert in reference
        // But here we are testing create, which internally uses clone and initialize
        // The difference: buggy version allows transferOwnership to zero address
        // This affects the ownedBy parameter processing in create

        address cloneAddress = c.create(encodedParams, ownedBy);

        // Assert that the clone address is a contract
        assertTrue(cloneAddress.code.length > 0);
    }
}

contract DummyRound {
    function initialize(bytes calldata, address) external {}
}

contract DummyAlloSettings {}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract (sets owner to address(this))
        c.initialize();

        // Set up roundImplementation and alloSettings to non-zero addresses so create works
        address dummy = address(0x1234);
        address payable dummyPayable = payable(dummy);
        c.updateRoundImplementation(dummyPayable);
        c.updateAlloSettings(dummy);

        // Make this contract a program operator
        // programOperators mapping is public but we need to set it - we can call create directly
        // but first we need to be a program operator; we can prank as owner which is address(this)
        // We need to set programOperators[address(this)] = true - but no setter exists.
        // The only way to set programOperators is via the contract's internal logic.
        // Actually the contract has no function to add program operators, so we cannot make any caller a program operator.
        // This is a design flaw for the test - but we need a different approach.
        // Let's instead focus on the difference: transferOwnership behavior change.
        // We can directly test transferOwnership with address(0) after create has been called.
        // But the bug is in transferOwnership, not in create.
        // The scenario: as owner, call transferOwnership(address(0)).
        // Reference: reverts with "Ownable: new owner is the zero address"
        // Bug: succeeds, making owner = address(0)

        // Reset contract - deploy fresh
        c = new C();
        c.initialize(); // sets owner to this test contract

        // Test: owner tries to transfer ownership to zero address
        bool success;
        try c.transferOwnership(address(0)) {
            success = true;
        } catch {
            success = false;
        }

        // In reference C, transferOwnership(address(0)) reverts because of the require(newOwner != address(0)) check.
        // In the buggy version, that require is removed, so it succeeds.
        // Actually checking: the buggy version has the require removed, so it succeeds.
        // The reference has the require, so it reverts.
        // Therefore success should be false for reference (revert), true for bug.
        // We assertTrue(success) - false for reference, true for bug. Test passes on reference (assertTrue(false) fails? No! assertTrue(false) would fail, and we want the test to FAIL on the buggy version.
        // Wait: we want reference to pass, bug to fail.
        // If assertTrue(success), reference: success=false, so assertTrue(false) fails -> test fails on reference! That's wrong.
        // We want reference to pass, so we need an assertion that is TRUE for reference.
        // Reference: transferOwnership(address(0)) reverts -> success=false.
        // So assertTrue(!success) would be true for reference (since !success = true).
        // Bug: success=true, so !success=false -> assertTrue(!success) fails -> test fails on bug. Good.

        assertTrue(!success);
    }
}

