pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: call initialize() to set up ownership
        c.initialize();

        // Set a program operator
        address operator = address(0x1234);
        // We need to prank as owner to add operator and set addresses
        // After initialize, owner is this contract (caller of initialize)
        address owner = address(this);

        // Add operator
        vm.prank(owner);
        c.addProgramOperator(operator);

        // Set roundImplementation to a non-zero address
        address mockRound = address(0x5678);
        vm.prank(owner);
        c.updateRoundImplementation(payable(mockRound));

        // Set alloSettings to a non-zero address via updateAlloSettings
        address validAlloSettings = address(0x9ABC);
        vm.prank(owner);
        c.updateAlloSettings(validAlloSettings);

        // Now call create as operator with empty encodedParameters
        bytes memory emptyParams = "";
        vm.prank(operator);
        // The reference contract will have alloSettings = validAlloSettings (non-zero), so create succeeds
        // The bug contract will have alloSettings = address(0) (set in updateAlloSettings), so create reverts
        bool ok;
        try c.create(emptyParams, operator) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference holds: ok == true (create succeeds because alloSettings != 0)
        // The bug breaks: ok == false (create reverts because alloSettings == 0)
        assertTrue(ok, "create should succeed but buggy version reverts");
    }
}

