import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deployer address
        address deployer = address(this);

        // Set up program operator
        c.programOperators(deployer);
        vm.prank(deployer);
        c.initialize();

        // Set up roundImplementation and alloSettings
        address mockRoundImpl = address(0xdead);
        address mockAlloSettings = address(0xbeef);
        vm.prank(deployer);
        c.updateRoundImplementation(payable(mockRoundImpl));
        vm.prank(deployer);
        c.updateAlloSettings(mockAlloSettings);

        // Call create()
        bytes memory emptyParams = "";
        vm.prank(deployer);
        c.create(emptyParams, deployer);

        // After create(), try to call initialize again
        vm.prank(deployer);
        bool ok;
        try c.initialize() {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, initialize should already be called, so second call reverts (ok = false)
        // In bug, the bug might allow a second initialization (ok = true)
        // Assert that initialize reverts (reference behavior)
